package net.minecraft.core;
import java.util.*;import net.minecraft.resources.ResourceLocation;import net.minecraft.world.item.crafting.RecipeSerializer;
public final class Registry<T>{
 private final Map<ResourceLocation,T> values=new HashMap<>();private final Map<T,ResourceLocation> names=new IdentityHashMap<>();
 public T get(ResourceLocation id){return values.get(id);}
 public void put(String id,T value){ResourceLocation key=ResourceLocation.parse(id);values.put(key,value);names.put(value,key);}
 public boolean containsKey(ResourceLocation id){return values.containsKey(id);}
 public ResourceLocation getKey(T value){ResourceLocation key=names.get(value);return key!=null?key:value instanceof RecipeSerializer<?> serializer?ResourceLocation.parse(serializer.id()):null;}
}

