package net.minecraft.world.level.storage;
import java.util.*;import net.minecraft.world.level.saveddata.SavedData;import net.minecraft.nbt.CompoundTag;
public class DimensionDataStorage{
 public final Map<String,SavedData> data=new HashMap<>();public final Map<String,CompoundTag> raw=new HashMap<>();public int writes,reads;
 @SuppressWarnings("unchecked")public <T extends SavedData>T get(SavedData.Factory<T> factory,String id){reads++;var saved=data.get(id);if(saved!=null)return (T)saved;if(!raw.containsKey(id))return null;try{T loaded=factory.loader().apply(raw.get(id).copy(),null);data.put(id,loaded);return loaded;}catch(RuntimeException error){return null;}}
 public void set(String id,SavedData value){writes++;data.put(id,value);}
}

